#include "task_exact_read_clock.hpp"
#include "task_exact_execution.hpp"
#include "resident/kernel/world_bundle.hpp"
#include "resident/domains/actor_foundation/character_condition_world.hpp"
namespace hanmo::resident {namespace {
const TaskExactStartSource*start(const TaskState&s,const StableId&id){const TaskExactStartSource*out=nullptr;if(s.exact_execution)for(const auto&row:s.exact_execution->starts.rows())if(row.second.action_id==id){if(out)return nullptr;out=&row.second;}return out;}
const TaskExactTerminalSource*end(const TaskState&s,const StableId&id){const TaskExactTerminalSource*out=nullptr;if(s.exact_execution)for(const auto&row:s.exact_execution->terminals.rows())if(row.second.action_id==id){if(out)return nullptr;out=&row.second;}return out;}
}
Outcome<std::optional<TaskExactReadClock>>capture_task_exact_read_clock(const WorldBundle&w,const CharacterConditionWorldRead*body){if(!w.tasks.exact_execution)return {true,std::nullopt,{}};if(!w.world_timeline||!w.action_elapsed)return {false,{},common_failure("TaskExactClockPairRequired").error};if(w.tasks.exact_execution->version==2&&!body)return {false,{},common_failure("TaskExactOriginalLifeSourcesRequired",{},ErrorKind::unsupported_capability).error};auto at=w.actual_phase_moment();if(!at.ok)return {false,{},at.error};return {true,TaskExactReadClock{&*w.action_elapsed,&w.world_timeline->scale_ref,std::move(at.value),&w,body},{}};}
Outcome<const TaskExactTerminalSource*> read_task_exact_death_clock(const CommonStore&c,const TaskState&s,const TaskExactReadClock&clock,const StableId&action){
 const auto*done=end(s,action);if(!done||!done->participant_death)return {true,nullptr,{}};
 const auto*w=clock.world;
 if(!s.exact_execution||s.exact_execution->version!=2||!w||&w->common!=&c||&w->tasks!=&s||
    !w->catalog||!w->catalog->tasks||!w->world_timeline||clock.scale!=&w->world_timeline->scale_ref||!w->action_elapsed||clock.elapsed!=&*w->action_elapsed||!clock.original_body)
  return {false,{},common_failure("TaskExactOriginalLifeSourcesRequired",action,ErrorKind::unsupported_capability).error};
 auto body=clock.original_body->sources();if(!body.ok)return {false,{},body.error};
 if(&body.value.common!=&c||body.value.deaths!=&w->family_life||!body.value.life_sources||body.value.elapsed!=clock.elapsed)
  return {false,{},common_failure("TaskExactLifeCandidateMismatch",action,ErrorKind::internal).error};
 auto same=compare_world_moments(body.value.actual_now,clock.at);if(!same.ok)return {false,{},same.error};if(same.value)return {false,{},common_failure("TaskExactLifeMomentMismatch",action,ErrorKind::internal).error};
 TaskExactLifeSources life{c,w->family_life,*body.value.life_sources,body.value.actual_now};
 auto actual=read_original_task_death_terminal(c,s,*w->catalog->tasks,w->catalog->identity,action,done->participant_death->death_ref,life);if(!actual.ok)return actual;
 auto released=guard_task_exact_release(c,s,*clock.elapsed,action,&life);if(!released.ok)return {false,{},released.error};
 if(c.action(action)||s.actions.find(action))return {false,{},common_failure("TaskExactDeathActionNotReleased",action).error};
 same=compare_world_moments(done->finished_at,clock.at);if(!same.ok)return {false,{},same.error};if(same.value>0)return {false,{},common_failure("TaskExactDeathTerminalInFuture",action).error};
 return actual;
}
Status validate_task_exact_active_clock(const CommonStore&c,const TaskState&s,const TaskExactReadClock&clock,const StableId&action,Integer started,Integer duration){const auto*w=clock.world;if(!w||&w->common!=&c||&w->tasks!=&s||!w->world_timeline||clock.scale!=&w->world_timeline->scale_ref||!w->action_elapsed||clock.elapsed!=&*w->action_elapsed)return common_failure("TaskExactClockCandidateMismatch",action,ErrorKind::internal);const auto*begun=start(s,action);const auto*entry=clock.elapsed?find_fixed_elapsed(*clock.elapsed,action):nullptr;const auto*actual=c.action(action);if(!begun||!entry||!actual||end(s,action)||begun->started_at.half_day_tick!=started||begun->required_half_days!=duration||entry->execution_source_ref!=begun->id||actual->start_tick!=started)return common_failure("TaskExactActiveClockSourceMismatch",action);auto at=compare_world_moments(entry->last_settled_at,clock.at);if(!at.ok)return {false,{},at.error};if(at.value)return common_failure("TaskExactActiveClockNotSettled",action);auto valid=validate_fixed_elapsed_value(*entry,clock.at,*clock.scale);if(!valid.ok)return valid;auto remaining=fixed_elapsed_remaining_ticks(*entry,*clock.scale);if(!remaining.ok)return {false,{},remaining.error};return actual->remaining_ticks==remaining.value?common_success():common_failure("TaskExactActiveRemainingMismatch",action);}
Status validate_task_exact_completion_clock(const CommonStore&c,const TaskState&s,const TaskExactReadClock&clock,const StableId&action,Integer started,Integer duration,Integer tick){auto valid=validate_task_exact_active_clock(c,s,clock,action,started,duration);if(!valid.ok)return valid;const auto*entry=find_fixed_elapsed(*clock.elapsed,action);const auto*running=std::get_if<ElapsedRunning>(&entry->timing);if(!running||clock.at.half_day_tick!=tick||c.action(action)->remaining_ticks!=0)return common_failure("TaskExactCompletionClockMismatch",action);auto at=compare_world_moments(running->completion_due_at,clock.at);if(!at.ok)return {false,{},at.error};return at.value==0?common_success():common_failure("TaskExactCompletionGateNotDue",action);}
Status validate_task_exact_historical_result_clock(const CommonStore&c,const TaskState&s,const TaskExactReadClock&clock,const StableId&action,const StableId&result,Integer tick){const auto*begun=start(s,action);if(!begun||!c.state().facts.find(result))return common_failure("TaskExactHistoricalSourceMissing",result);if(const auto*done=end(s,action)){if(done->finished_at.half_day_tick!=tick)return common_failure("TaskExactHistoricalTimeMismatch",result);bool actual=false;for(const auto&source:done->actual_result_sources)if(source.id==result)actual=true;if(!actual)return common_failure("TaskExactHistoricalResultUnbound",result);auto at=compare_world_moments(done->finished_at,clock.at);if(!at.ok)return {false,{},at.error};return at.value<=0?common_success():common_failure("TaskExactHistoricalResultInFuture",result);}return validate_task_exact_completion_clock(c,s,clock,action,begun->started_at.half_day_tick,begun->required_half_days,tick);}
}
